 table(['Direction','Steps','Active','Query changed','Group changed','Within-group switch','IoU changed','Better/worse'],[[r['source']+'→'+r['target'],r['steps'],r['active'],r['query_changed'],r['group_changed'],r['same_group_query_switch'],r['IoU_changed'],str(r['better_vs_zero'])+'/'+str(r['worse_vs_zero'])] for r in stepinfo]),'',
